#!/usr/bin/env python3
import sys
import json
import time
from urllib import request, error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
TEST_PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30
MAX_TOKENS = 20


def load_models_from_json(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    models = []

    def add_model(name):
        if isinstance(name, str):
            name = name.strip()
            if name:
                models.append(name)

    def extract(obj):
        if isinstance(obj, list):
            for item in obj:
                if isinstance(item, str):
                    add_model(item)
                elif isinstance(item, dict):
                    for key in ("id", "model", "name"):
                        if key in item and isinstance(item[key], str):
                            add_model(item[key])
                            break
        elif isinstance(obj, dict):
            # Common config shapes
            if "models" in obj:
                extract(obj["models"])
                return
            if "model_list" in obj:
                extract(obj["model_list"])
                return

            # If dict keys are model names (e.g. {"gpt-4": {...}, "llama3": {...}})
            if obj and all(isinstance(v, dict) for v in obj.values()):
                for k in obj.keys():
                    add_model(k)
                return

            # Single model object
            for key in ("id", "model", "name"):
                if key in obj and isinstance(obj[key], str):
                    add_model(obj[key])

    extract(data)

    # Deduplicate while preserving order
    seen = set()
    unique_models = []
    for m in models:
        if m not in seen:
            seen.add(m)
            unique_models.append(m)

    return unique_models


def extract_response_text(resp_json):
    choices = resp_json.get("choices")
    if not isinstance(choices, list) or not choices:
        return ""

    first = choices[0]
    if not isinstance(first, dict):
        return ""

    # Chat format
    msg = first.get("message")
    if isinstance(msg, dict):
        content = msg.get("content")
        if isinstance(content, str):
            return content.strip()
        if isinstance(content, list):
            parts = []
            for part in content:
                if isinstance(part, dict) and isinstance(part.get("text"), str):
                    parts.append(part["text"])
            return "".join(parts).strip()

    # Completion format fallback
    text = first.get("text")
    if isinstance(text, str):
        return text.strip()

    return ""


def extract_error_message(raw_text):
    raw_text = (raw_text or "").strip()
    if not raw_text:
        return "Unknown error"

    try:
        obj = json.loads(raw_text)
        if isinstance(obj, dict):
            err = obj.get("error")
            if isinstance(err, dict):
                return str(err.get("message") or err.get("type") or err)
            if isinstance(err, str):
                return err
            return str(obj)
    except Exception:
        pass

    return raw_text


def temperature_not_supported(msg):
    m = (msg or "").lower()
    return (
        "temperature" in m
        and ("not supported" in m or "unsupported" in m or "unknown" in m or "invalid" in m)
    )


def make_request(model_name, include_temperature=True):
    payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": TEST_PROMPT}],
        "max_tokens": MAX_TOKENS,
    }
    if include_temperature:
        payload["temperature"] = 0

    body = json.dumps(payload).encode("utf-8")
    req = request.Request(
        API_URL,
        data=body,
        method="POST",
        headers={"Content-Type": "application/json"},
    )

    try:
        with request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
        obj = json.loads(raw)
        return True, extract_response_text(obj), None, False

    except error.HTTPError as e:
        err_body = e.read().decode("utf-8", errors="replace")
        msg = extract_error_message(err_body)
        if include_temperature and temperature_not_supported(msg):
            return False, "", msg, True
        return False, "", f"HTTP {e.code}: {msg}", False

    except error.URLError as e:
        return False, "", f"URL error: {e.reason}", False

    except Exception as e:
        return False, "", str(e), False


def preview_text(s, limit=50):
    s = (s or "").replace("\n", " ").replace("\r", " ")
    return s[:limit]


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <models_config.json>")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        models = load_models_from_json(config_path)
    except Exception as e:
        print(f"Failed to load config file: {e}")
        sys.exit(1)

    if not models:
        print("No models found in config file.")
        sys.exit(1)

    results = []
    working = 0
    failed = 0

    for model in models:
        start = time.time()

        ok, text, err_msg, should_retry_without_temp = make_request(model, include_temperature=True)

        # Retry once without temperature if unsupported
        if should_retry_without_temp:
            ok, text, err_msg, _ = make_request(model, include_temperature=False)

        latency = time.time() - start

        if ok:
            status = "PASS"
            response_preview = preview_text(text, 50)
            working += 1
        else:
            status = "FAIL"
            response_preview = preview_text(f"ERROR: {err_msg}", 50)
            failed += 1

        results.append({
            "model": model,
            "status": status,
            "latency": f"{latency:.2f}s",
            "response": response_preview,
        })

    # Table formatting
    model_w = max(len("Model"), max(len(r["model"]) for r in results))
    status_w = max(len("Status"), max(len(r["status"]) for r in results))
    latency_w = max(len("Latency"), max(len(r["latency"]) for r in results))
    response_w = max(len("Response"), max(len(r["response"]) for r in results))

    fmt = f"{{:<{model_w}}} | {{:<{status_w}}} | {{:>{latency_w}}} | {{:<{response_w}}}"
    sep = "-" * (model_w + status_w + latency_w + response_w + 9)

    print(fmt.format("Model", "Status", "Latency", "Response"))
    print(sep)
    for r in results:
        print(fmt.format(r["model"], r["status"], r["latency"], r["response"]))

    total = len(results)
    print()
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
